```python
import dlt
from pyspark.sql.functions import col, to_date, sum as _sum, count, avg

@dlt.table(
    comment="Raw NYC Taxi trip records, as ingested",
    table_properties={"quality": "bronze"},
)
def bronze_trips():
    return (
        spark.readStream
        .format("cloudFiles")
        .option("cloudFiles.format", "csv")
        .option("cloudFiles.schemaLocation", "/checkpoints/trips_schema")
        .load("/Volumes/nyc_taxi/bronze/raw_files/")
    )

@dlt.table(
    comment="Cast, deduplicated, quality-checked trip records",
    table_properties={"quality": "silver"},
)
@dlt.expect_or_drop("valid_fare", "fare_amount > 0")
@dlt.expect_or_drop("valid_distance", "trip_distance > 0")
@dlt.expect_or_fail("valid_vendor", "VendorID IS NOT NULL")
def silver_trips():
    return (
        dlt.read_stream("bronze_trips")
        .withColumn("fare_amount", col("fare_amount").cast("double"))
        .withColumn("tpep_pickup_datetime", col("tpep_pickup_datetime").cast("timestamp"))
        .dropDuplicates(["VendorID", "tpep_pickup_datetime"])
    )

@dlt.table(
    comment="Daily revenue per vendor, recomputed over a 3-day trailing window",
    table_properties={"quality": "gold", "pipelines.reset.allowFullRefresh": "false"},
)
def gold_daily_revenue():
    return (
        dlt.read("silver_trips")
        .filter(to_date("tpep_pickup_datetime") >= current_date() - 3)
        .groupBy("VendorID", to_date("tpep_pickup_datetime").alias("trip_date"))
        .agg(
            count("*").alias("trip_count"),
            _sum("fare_amount").alias("total_revenue"),
            avg("fare_amount").alias("avg_fare"),
        )
    )
```

